    try {
      await reservation.turnoutLease.release();
    } catch (error) {
      __dccSmartLog(
        "ERROR",
        transitionName +
        ": turnout release failed after arrival",
        {
          error:
            __dccSmartErrorText(
              error
            ),
        }
      );
    }

    if (previousLease) {
      try {
        await previousLease.release();
      } catch (error) {
        __dccSmartLog(
          "ERROR",
          transitionName +
          ": previous block lease release failed",
          {
            error:
              __dccSmartErrorText(
                error
              ),
          }
        );
      }
    }

    __dccSmartLog(
      "INFO",
      transitionName +
      ": arrival committed; previous resources released",
      {
        currentBlock:
          transition.to.name,
        loco:
          state.loco,
      }
    );
